#!/bin/bash
# Multi-node dlrmv4 launcher. Runs once per node (srun --ntasks-per-node=1, see job.sh): starts
# the container on this node, then runs NEXP timed runs of run_and_time.sh. There is no torchrun:
# on every node the trainer spawns GPUS_PER_NODE ranks itself and all nodes rendezvous over
# env:// at MASTER_ADDR:MASTER_PORT (NNODES / NODE_RANK come from Slurm).
# Generated by the submission packaging tool; see README.md section 5.
set -euo pipefail

if docker info >/dev/null 2>&1; then DOCKER=docker; else DOCKER="sudo docker"; fi

cd "$(dirname "$(readlink -f "$0")")"

# Vars without defaults
: "${DGXSYSTEM:?DGXSYSTEM not set}"
: "${CONT:?CONT not set}"
: "${DATADIR:?DATADIR not set}"
: "${LOGDIR:?LOGDIR not set}"
: "${ROOT_SEED:?ROOT_SEED not set}"
: "${SLURM_JOB_ID:?run under Slurm (sbatch job.sh)}"

# Vars with defaults
: "${NEXP:=1}"
: "${CLEAR_CACHES:=1}"
: "${CHECK_COMPLIANCE:=1}"
: "${MLPERF_RULESET:=6.1.0}"
: "${CONT_NAME:=mlperf_dlrmv4}"

readonly _config_file="./config_${DGXSYSTEM}.sh"
readonly _cont_name="${CONT_NAME}"
[ -f "${_config_file}" ] || { echo "no ${_config_file} in $(pwd)" >&2; exit 1; }

# Every variable the config exports is passed to the container (re-sourced in a clean shell).
mapfile -d '' -t _config_kv < <(env -i bash -c ". ${_config_file} >/dev/null && for v in \$(compgen -e); do
  case \$v in PWD|SHLVL|_) continue ;; esac; printf '%s=%s\0' \"\$v\" \"\${!v}\"; done")
_env_args=()
_nn=1
for _kv in "${_config_kv[@]}"; do
  _env_args+=("--env=${_kv}")
  [ "${_kv%%=*}" = NNODES ] && _nn=${_kv#*=}
done
if [ "${_nn}" != "${SLURM_NNODES:-1}" ]; then
  echo "${_config_file} is a ${_nn}-node configuration but the allocation has ${SLURM_NNODES:-1} node(s)" >&2; exit 1
fi

mkdir -p "${LOGDIR}"

# ---- container (same flags as the submitted runs)
${DOCKER} container rm -f "${_cont_name}" >/dev/null 2>&1 || true
${DOCKER} run --detach --name="${_cont_name}" \
  --network=host \
  --ipc=host \
  --shm-size=64g \
  --device=/dev/kfd \
  --device=/dev/dri \
  --group-add video \
  --cap-add=SYS_PTRACE \
  --cap-add=CAP_SYS_ADMIN \
  --cap-add=IPC_LOCK \
  --ulimit memlock=-1:-1 \
  --ulimit stack=67108864:67108864 \
  --security-opt seccomp=unconfined \
  --privileged \
  --volume="${DATADIR}:/data/mlperf_dlrm_v4" \
  --volume="$(pwd):/workspace/recommendation" \
  --volume="${LOGDIR}:/results" \
  --workdir="/workspace/recommendation" \
  "${CONT}" sleep infinity
trap '${DOCKER} container rm -f "${_cont_name}" >/dev/null 2>&1 || true' EXIT
sleep 5
${DOCKER} exec "${_cont_name}" true

# The submitted runs required every GPU at performance level "auto" (warn only).
if command -v rocm-smi >/dev/null 2>&1 && rocm-smi --showperflevel 2>/dev/null | grep -iqE "Performance Level: *(perf_determinism|manual|low)"; then
  echo "WARNING: not all GPUs on $(hostname) are at performance level 'auto' (rocm-smi --setperflevel auto)" >&2
fi

# ---- rendezvous, resolved on the host (the image carries no Slurm client)
MASTER_ADDR=$(scontrol show hostnames "${SLURM_JOB_NODELIST}" | head -n 1)
: "${MASTER_ADDR:?could not resolve the first node of the allocation (scontrol)}"
export MASTER_ADDR
export MASTER_PORT=${MASTER_PORT:-$(( 20000 + SLURM_JOB_ID % 20000 ))}
# TCP bootstrap interface: the default-route interface unless set. [SITE-SPECIFIC] Set it to
# the routable host interface if the default route is not on it.
export NCCL_SOCKET_IFNAME=${NCCL_SOCKET_IFNAME:-$(ip -o -4 route show to default | awk '{print $5; exit}')}
echo "node $(hostname): SLURM_NODEID=${SLURM_NODEID} of ${SLURM_NNODES}, master ${MASTER_ADDR}:${MASTER_PORT}, bootstrap ifname ${NCCL_SOCKET_IFNAME}"

for _experiment_index in $(seq 1 "${NEXP}"); do
  # same seed on every node of the run, different for every run
  _seed=$(( ROOT_SEED + 10#${SLURM_ARRAY_TASK_ID:-0} * 100 + 10#${_experiment_index} ))
  _base="${SLURM_JOB_ID}_${_experiment_index}"
  {
    echo "Beginning trial ${_experiment_index} of ${NEXP} (seed ${_seed})"
    if [ "${CLEAR_CACHES}" = 1 ]; then
      # Host-side flush, as for the submitted runs. run_and_time.sh flushes again inside the
      # (privileged) container and the trainer logs the MLPerf cache_clear event itself.
      echo -n "Clearing cache on " && hostname && sync && sudo -n /sbin/sysctl -q vm.drop_caches=3
    fi
    ${DOCKER} exec "${_env_args[@]}" \
      --env=NNODES="${SLURM_NNODES}" \
      --env=NODE_RANK="${SLURM_NODEID}" \
      --env=MASTER_ADDR="${MASTER_ADDR}" \
      --env=MASTER_PORT="${MASTER_PORT}" \
      --env=NCCL_SOCKET_IFNAME="${NCCL_SOCKET_IFNAME}" \
      --env=SEED="${_seed}" \
      --env=CLEAR_CACHES="${CLEAR_CACHES}" \
      --env=RUN_NAME="${_base}" \
      --env=MLPERF_LOG_PATH="/results/${_base}.log" \
      "${_cont_name}" bash ./run_and_time.sh
  } 2>&1 | tee "${LOGDIR}/${_base}_node${SLURM_NODEID}.out"

  # rank 0 (node 0) writes the MLPerf log
  if [ "${CHECK_COMPLIANCE}" = 1 ] && [ "${SLURM_NODEID}" = 0 ]; then
    ${DOCKER} exec "${_cont_name}" \
      python3 -m mlperf_logging.compliance_checker --usage training \
      --ruleset "${MLPERF_RULESET}" \
      --log_output "/results/compliance_${_base}.out" \
      "/results/${_base}.log" || echo "WARNING: compliance check failed for ${_base}.log"
  fi
done
echo "Number of experiments ${NEXP}; MLPerf logs: ${LOGDIR}/${SLURM_JOB_ID}_<n>.log"
